388: [profile.release]
389: strip = true
390: lto = "fat"
391: 
392: # This profile is meant to mimic the `release` profile as closely as
393: # possible, but using settings that are more beneficial for iterative
394: # development. That is, the `release` profile is intended for actually
395: # building the release, where as `profiling` is meant for building `uv`
396: # for running benchmarks.
397: #
398: # The main differences here are to avoid stripping debug information
399: # and disabling lto. This does result in a mismatch between our release
400: # configuration and our benchmarking configuration, which is unfortunate.
401: # But compile times with `lto = true` are completely untenable:
402: #
403: #     $ cargo b --profile profiling -p uv
404: #        Compiling uv-cli v0.0.1 (/home/andrew/astral/uv/crates/uv-cli)
405: #        Compiling uv v0.2.34 (/home/andrew/astral/uv/crates/uv)
406: #         Finished `profiling` profile [optimized + debuginfo] target(s) in 3m 47s
407: #
408: # Using `lto = "thin"` brings a massive improvement, but it's still slow:
409: #
410: #     $ cargo b --profile profiling -p uv
411: #        Compiling uv v0.2.34 (/home/andrew/astral/uv/crates/uv)
412: #         Finished `profiling` profile [optimized + debuginfo] target(s) in 53.98s
413: #
414: # But with `lto = false`:
415: #
416: #     $ cargo b --profile profiling -p uv
417: #        Compiling uv v0.2.34 (/home/andrew/astral/uv/crates/uv)
418: #         Finished `profiling` profile [optimized + debuginfo] target(s) in 30.09s
419: #
420: # We get more reasonable-ish compile times. At least, it's not enough
421: # time to get up and get a cup of coffee before it completes.
422: #
423: # This setup does risk that we are measuring something in benchmarks
424: # that we are shipping, but in order to make those two the same, we'd
425: # either need to make compile times way worse for development, or take
426: # a hit to binary size and a slight hit to runtime performance in our
427: # release builds.
428: [profile.profiling]
429: inherits = "release"
430: strip = false
431: debug = "full"
432: lto = false
433: 
434: # Profile for fast test execution: Skip debug info generation, and
435: # apply basic optimization, which speed up build and running tests.
436: [profile.fast-build]
437: inherits = "dev"
438: opt-level = 1
439: debug = 0
440: strip = "debuginfo"
441: 
442: # Profile for faster builds: Skip debug info generation, for faster
443: # builds of smaller binaries.
444: [profile.no-debug]
445: inherits = "dev"
446: debug = 0
447: strip = "debuginfo"
448: 
449: # Profile to build a minimally sized binary for uv-build
450: [profile.minimal-size]
451: inherits = "release"
452: opt-level = "z"
453: # This will still show a panic message, we only skip the unwind
454: panic = "abort"
455: codegen-units = 1
456: 
457: # The profile that 'cargo dist' will build with.
458: [profile.dist]
459: inherits = "release"

