12: /// This helps determine whether the system is using the `gnueabihf` (hard-float) ABI or `gnueabi` (soft-float) ABI.
13: ///
14: /// More information on this can be found in the [Debian ARM Hard Float Port documentation](https://wiki.debian.org/ArmHardFloatPort#VFP).
15: #[cfg(target_os = "linux")]
16: pub(crate) fn detect_hardware_floating_point_support() -> Result<bool, Error> {
17:     let cpu_info = CpuInfo::current().map_err(Error::other)?;
18:     if let Some(features) = cpu_info.fields.get("Features") {
19:         if has_hardware_float_features(features) {
20:             return Ok(true);
21:         }
22:     }
23: 
24:     Ok(false) // Default to soft-float (gnueabi) if no hardware float feature is found
25: }
